import{_ as t,o,c as r,a5 as u}from"./chunks/framework.DJo0M80U.js";const i=JSON.parse('{"title":"vue-router 的动态路由","description":"vue router 的动态路由是指在应用程序运行时动态添加、删除或修改路由配置的功能。动态路由通常用于处理用户权限控制、多语言支持、动态菜单等场景。通过 vue router 的动态路由，可以在应用初始化时不加载所有的路由，而是根据实际情况（如用户角色、权限等）动态地决定哪些路。","frontmatter":{"title":"vue-router 的动态路由","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"vue router 的动态路由是指在应用程序运行时动态添加、删除或修改路由配置的功能。动态路由通常用于处理用户权限控制、多语言支持、动态菜单等场景。通过 vue router 的动态路由，可以在应用初始化时不加载所有的路由，而是根据实际情况（如用户角色、权限等）动态地决定哪些路。","sidebarWeight":17,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/`vue-router` 的动态路由.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/vue-router 的动态路由.md","filePath":"posts/Vue系统教程/04-路由与状态管理/vue-router 的动态路由.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/vue-router 的动态路由.md"};function n(s,e,d,p,c,v){return o(),r("div",null,[...e[0]||(e[0]=[u('<div><h1 id="vue-router-的动态路由" tabindex="-1">vue-router 的动态路由 <a class="header-anchor" href="#vue-router-的动态路由" aria-label="Permalink to &quot;vue-router 的动态路由&quot;">​</a></h1><blockquote><p>本节目标：理解“vue-router 的动态路由”的核心思路，并能把它用于实际开发或面试表达。 <code>vue-router</code> 的动态路由是指在应用程序运行时动态添加、删除或修改路由配置的功能。动态路由通常用于处理用户权限控制、多语言支持、动态菜单等场景。通过 <code>vue-router</code> 的动态路由，可以在应用初始化时不加载所有的路由，而是根据实际情况（如用户角色、权限等）动态地决定哪些路由应该添加到路由配置中。</p></blockquote><p>以下是一个简单的示例： // 假设我们有一个 Vue 实例 const router = new VueRouter({ routes: [ { path: &#39;/home&#39;, component: HomeComponent } ] }); // 之后我们可以在需要时动态添加新的路由 const newRoute = { path: &#39;/admin&#39;, component: AdminComponent }; router.addRoute(newRoute); // 也可以删除某个路由 router.removeRoute(&#39;/admin&#39;);</p><p>使用动态路由的主要优势是灵活性，可以根据具体业务需求在运行时调整路由配置，从而提升应用的适应性和扩展性。</p><p>使用 vue-router 的动态路由时，路由会立即生效。也就是说，当你使用 router.addRoute 方法添加新的路由或使用 router.removeRoute 方法删除现有路由后，这些更改会立即反映在应用程序中。</p></div>',1)])])}const m=t(a,[["render",n]]);export{i as __pageData,m as default};
